    enable = true;
    adminAddr = "webmaster@localhost";
    extraModules = [
      "proxy"
      "proxy_fcgi"
      "rewrite"
      "userdir"
      "headers"
      "ssl"
      "status"
      { name = "wsgi"; path = "${pkgs.apacheHttpdPackages.mod_wsgi}/modules/mod_wsgi.so"; }
    ];
    extraConfig = ''
      ServerName node.test
      ServerSignature On
      TraceEnable Off
      Listen 443
      WSGISocketPrefix /run/httpd/wsgi

      <Location /server-status>
          SetHandler server-status
          Require local
      </Location>

